      "name": "DialogClose",
      "parent": "DialogContent",
      "primitive": "Dialog.CloseTrigger",
      "slot": "dialog-close-trigger"
    },
    {
      "element": "div",
      "name": "DialogFooter",
      "parent": "DialogContent",
      "slot": "dialog-footer"
    }
  ],
  "props": {
    "bottomStickOnMobile": {
      "defaultValue": true,
      "description": "Dock content to the viewport bottom on small screens.",
      "type": "boolean"
