  },
  "scenarios": [
    {
      "assertions": [
        "defaults modal, lazyMount and unmountOnExit to true",
        "supports controlled and uncontrolled open state"
      ],
      "name": "root-state"
    },
    {
      "assertions": [
        "omits the backdrop when modal is false",
        "portals content",
        "exposes an accessible title"
      ],
      "name": "composition"
    },
    {
      "assertions": [
        "renders every size",
        "shows the close action by default",
        "supports mobile bottom docking"
      ],
      "name": "content"
    }
  ],
  "strategy": "ark"
} as const;

export const dialogOverlayVariants = tv({
